private static final class ArrayArrayIndexOutOfBounds extends ArrayIndexOutOfBoundsException {}

private static long readVarint(byte[] wire, int[] hold, int end) {
    int start = hold[0];
    if (start >= end) {
        throw new ArrayIndexOutOfBounds();
    }
    int first = wire[start] & 255;
    int width = 1 << (first >>> 6);
    if (start + width > end) {
        throw new ArrayIndexOutOfBounds();
    }
    long value = first & 0x3f;
    for (int i = 1; i < width; i++) {
        value = (value << 8) | (wire[start + i] & 255);
    }
    hold[0] = start + width;
    return value;
}

private static long readNumber(byte[] wire, int position, int width) {
    long value = 0;
    for (int i = 0; i < width; i++) {
        value = (value << 8) | (wire[position + i] & 255);
    }
    return value;
}
